class School:
    def __init__(self):
        self._students = {}
        self._added = []

    def add_student(self, name, grade):
        if name in self._students.get(grade, set()):
            self._added.append(False)
            return
        self._students.setdefault(grade, set()).add(name)
        self._added.append(True)

    def roster(self):
        return sorted(
            name
            for grade, names in self._students.items()
            for name in names
        )

    def grade(self, grade_number):
        return sorted(self._students.get(grade_number, set()))

    def added(self):
        return self._added

